import { inrCompact, pct } from "../../shared/format.ts";
import type { Insight } from "../../shared/types.ts";
import { all } from "../db.ts";
import type { DealScope } from "./deals.ts";
import { analytics, dashboard, forecast } from "./metrics.ts";

/**
 * Rule-based insight engine. Each insight is computed from stored data with
 * explicit thresholds and shows the evidence behind it. Nothing here is
 * generated by a language model, so numbers are always exact.
 */
export function generateInsights(scope: DealScope, viewerIsManager: boolean): Insight[] {
  const dash = dashboard(scope);
  const an = analytics(scope);
  const fc = forecast(scope);
  const k = dash.kpis;
  const out: Insight[] = [];
  const q = dash.period.label;

  // 1. Pipeline coverage
  if (k.coverage !== null && k.target > 0) {
    const cov = k.coverage;
    if (cov < 3) {
      out.push({
        id: "coverage",
        severity: cov < 1.5 ? "critical" : "warning",
        category: "Pipeline",
        title: `Pipeline coverage for ${q} is ${cov.toFixed(1)}× the remaining target`,
        explanation: `To close the ${inrCompact(k.gap)} gap you have ${inrCompact(k.openInPeriodAmount)} of open pipeline expected this quarter. A common rule of thumb is 3× coverage, given typical win rates.`,
        evidence: [
          { label: "Remaining target", value: inrCompact(k.gap) },
          { label: "Open pipeline this quarter", value: inrCompact(k.openInPeriodAmount) },
          { label: "Trailing win rate", value: pct(k.winRate) },
          { label: "Days left", value: String(dash.daysLeft) },
        ],
        action: cov < 1.5
          ? "Pull forward next-quarter deals that are ready, and run a focused prospecting sprint on existing customers."
          : "Prioritise late-stage deals this week and add qualified pipeline from referrals and existing customers.",
        link: "/pipeline?close=quarter",
      });
    } else {
      out.push({
        id: "coverage",
        severity: "info",
        category: "Pipeline",
        title: `Coverage is healthy at ${cov.toFixed(1)}× for ${q}`,
        explanation: "You have enough pipeline to hit target if deals convert at historical rates. Focus is on execution, not lead generation.",
        evidence: [
          { label: "Remaining target", value: inrCompact(k.gap) },
          { label: "Open pipeline this quarter", value: inrCompact(k.openInPeriodAmount) },
        ],
        action: "Protect late-stage deals: confirm next steps and decision dates on every Proposal and Negotiation deal.",
        link: "/forecast",
      });
    }
  }

  // 2. Forecast vs target
  if (fc.target > 0) {
    const likely = fc.won + fc.commit * 0.9 + fc.bestCase * 0.5;
    const r = likely / fc.target;
    if (r < 1) {
      out.push({
        id: "forecast_gap",
        severity: r < 0.75 ? "critical" : "warning",
        category: "Forecast",
        title: `Projected to reach about ${pct(r)} of the ${q} target`,
        explanation: `Projection assumes 90% of commit and 50% of best-case deals close. These are adjustable on the Forecast page — treat this as a planning range, not a prediction.`,
        evidence: [
          { label: "Won so far", value: inrCompact(fc.won) },
          { label: "Commit", value: inrCompact(fc.commit) },
          { label: "Best case", value: inrCompact(fc.bestCase) },
          { label: "Target", value: inrCompact(fc.target) },
        ],
        action: "Review best-case deals with each owner and agree what it takes to move them to commit.",
        link: "/forecast",
      });
    }
  }

  // 3. High-value deals at risk
  const open = (dash.atRisk ?? []).filter((d) => d.risk.level === "high");
  const highRisk = dash.riskSummary.find((r) => r.level === "high")!;
  if (highRisk.count > 0) {
    const top = open.slice(0, 3);
    out.push({
      id: "high_risk",
      severity: "critical",
      category: "Risk",
      title: `${highRisk.count} deals worth ${inrCompact(highRisk.amount)} are at high risk`,
      explanation: `Risk scores combine inactivity, missed close dates, time in stage, lapsed next steps, overdue follow-ups and missing decision-makers. Biggest exposure: ${top.map((d) => `${d.name} (${inrCompact(d.amount)})`).join(", ")}.`,
      evidence: top.map((d) => ({ label: d.name, value: `${d.risk.score}/100 · ${d.risk.factors[0]?.label ?? ""}` })),
      action: "Open each deal, review its risk factors and complete the recommended action within 48 hours.",
      link: "/pipeline?risk=high",
    });
  }

  // 4. Stale close dates
  const allOpen = fc.deals;
  const pastClose = allOpen.filter((d) => d.risk.factors.some((f) => f.code === "overdue_close"));
  if (pastClose.length >= 3) {
    out.push({
      id: "past_close",
      severity: "warning",
      category: "Data hygiene",
      title: `${pastClose.length} open deals have a close date in the past`,
      explanation: `These deals (${inrCompact(pastClose.reduce((s, d) => s + d.amount, 0))}) inflate the forecast. Either the date is wrong or the deal is no longer active.`,
      evidence: pastClose.slice(0, 4).map((d) => ({ label: d.name, value: `${d.owner_name} · due ${d.expected_close_date}` })),
      action: "Ask owners to update close dates or close these deals as lost before the next forecast call.",
      link: "/pipeline?flag=overdue_close",
    });
  }

  // 5. Follow-up discipline
  if (k.overdueTasks > 0) {
    const worst = an.reps.filter((r) => r.overdueTasks > 0).sort((a, b) => b.overdueTasks - a.overdueTasks);
    out.push({
      id: "overdue_followups",
      severity: k.overdueTasks >= 10 ? "warning" : "info",
      category: "Execution",
      title: `${k.overdueTasks} follow-ups are overdue`,
      explanation: viewerIsManager && worst.length
        ? `${worst[0].name} has the most (${worst[0].overdueTasks}). Overdue follow-ups are one of the strongest early signals of a deal going cold.`
        : "Overdue follow-ups are one of the strongest early signals of a deal going cold.",
      evidence: worst.slice(0, 4).map((r) => ({ label: r.name, value: `${r.overdueTasks} overdue` })),
      action: "Block 30 minutes today to clear overdue follow-ups, starting with the highest-value deals.",
      link: "/follow-ups?view=overdue",
    });
  }

  // 6. Best and worst lead sources
  const sources = an.bySource.filter((s) => s.won + s.lost >= 5);
  if (sources.length >= 3) {
    const sorted = [...sources].sort((a, b) => b.winRate - a.winRate);
    const best = sorted[0];
    const worst = sorted[sorted.length - 1];
    if (best.winRate - an.overall.winRate >= 0.08) {
      out.push({
        id: "best_source",
        severity: "opportunity",
        category: "Growth",
        title: `${best.name} deals win at ${pct(best.winRate)} vs ${pct(an.overall.winRate)} overall`,
        explanation: `Over the last four quarters, ${best.won} of ${best.won + best.lost} closed ${best.name.toLowerCase()} deals were won, with an average size of ${inrCompact(best.avgDeal)}.`,
        evidence: sorted.slice(0, 4).map((s) => ({ label: s.name, value: `${pct(s.winRate)} win · ${s.won + s.lost} closed` })),
        action: `Invest more in ${best.name.toLowerCase()} — e.g. a structured ask in every QBR, or partner co-selling incentives.`,
        link: "/analytics",
      });
    }
    if (an.overall.winRate - worst.winRate >= 0.08) {
      out.push({
        id: "worst_source",
        severity: "warning",
        category: "Efficiency",
        title: `${worst.name} converts at only ${pct(worst.winRate)}`,
        explanation: `${worst.lost} of ${worst.won + worst.lost} closed ${worst.name.toLowerCase()} deals were lost. Consider tighter qualification before these enter the pipeline.`,
        evidence: [
          { label: "Won", value: String(worst.won) },
          { label: "Lost", value: String(worst.lost) },
          { label: "Lost value", value: inrCompact(worst.lostAmount) },
        ],
        action: `Add a qualification checklist (budget, authority, need, timeline) for ${worst.name.toLowerCase()} leads.`,
        link: "/analytics",
      });
    }
  }

  // 7. Funnel bottleneck
  const conv = an.conversions.filter((c) => c.to !== "Closed Won");
  if (conv.length) {
    const weakest = [...conv].sort((a, b) => a.rate - b.rate)[0];
    out.push({
      id: "bottleneck",
      severity: "info",
      category: "Process",
      title: `Biggest drop-off is ${weakest.from} → ${weakest.to} (${pct(weakest.rate)})`,
      explanation: "Measured on deals created in the last four quarters, using stage history rather than current stage.",
      evidence: an.conversions.map((c) => ({ label: `${c.from} → ${c.to}`, value: pct(c.rate) })),
      action: `Review recent deals lost at ${weakest.from}. Look for a common objection or qualification gap.`,
      link: "/analytics",
    });
  }

  // 8. Top loss reason
  if (an.lossReasons.length) {
    const top = an.lossReasons[0];
    const totalLost = an.lossReasons.reduce((s, r) => s + r.count, 0);
    out.push({
      id: "loss_reason",
      severity: "info",
      category: "Win/loss",
      title: `"${top.reason}" is the top loss reason (${pct(top.count / totalLost)} of losses)`,
      explanation: `${top.count} deals worth ${inrCompact(top.amount)} were lost for this reason in the last four quarters.`,
      evidence: an.lossReasons.slice(0, 5).map((r) => ({ label: r.reason, value: `${r.count} deals` })),
      action: top.reason === "Price"
        ? "Introduce value-based ROI framing earlier and set a discount approval policy."
        : top.reason === "Chose competitor"
          ? "Build a competitive battlecard and run a win/loss review on the last five losses."
          : "Agree decision criteria and timeline with the buyer during Discovery.",
      link: "/analytics",
    });
  }

  // 9. Coaching opportunity (manager view)
  if (viewerIsManager) {
    const reps = an.reps.filter((r) => r.winRate > 0);
    const avg = an.overall.winRate;
    const lowest = [...reps].sort((a, b) => a.winRate - b.winRate)[0];
    if (lowest && avg - lowest.winRate >= 0.08) {
      out.push({
        id: "coaching",
        severity: "warning",
        category: "Coaching",
        title: `${lowest.name}'s win rate is ${pct(lowest.winRate)} vs team ${pct(avg)}`,
        explanation: `Average sales cycle is ${Math.round(lowest.avgCycle)} days with ${lowest.highRisk} high-risk open deals. This is a pattern worth a coaching conversation, not a verdict.`,
        evidence: reps.map((r) => ({ label: r.name, value: `${pct(r.winRate)} win · ${r.activities30} activities/30d` })),
        action: `Join ${lowest.name.split(" ")[0]}'s next two late-stage calls and review deal qualification together.`,
        link: "/analytics",
      });
    }
  }

  // 10. Concentration risk
  const commitBest = allOpen.filter((d) => d.forecast_category === "commit" || d.forecast_category === "best_case");
  const cbTotal = commitBest.reduce((s, d) => s + d.amount, 0);
  const top3 = [...commitBest].sort((a, b) => b.amount - a.amount).slice(0, 3);
  const top3Sum = top3.reduce((s, d) => s + d.amount, 0);
  if (cbTotal > 0 && top3Sum / cbTotal >= 0.5 && commitBest.length > 4) {
    out.push({
      id: "concentration",
      severity: "warning",
      category: "Forecast",
      title: `Three deals make up ${pct(top3Sum / cbTotal)} of commit + best case`,
      explanation: "The quarter depends heavily on a few deals. A single slip would materially change the outcome.",
      evidence: top3.map((d) => ({ label: d.name, value: inrCompact(d.amount) })),
      action: "Run a deal review on each of these with the owner and an executive sponsor.",
      link: "/forecast",
    });
  }

  // 11. Expansion opportunity: customers with past wins but nothing open
  const expansion = all<{ name: string; won: number; last: string }>(
    `SELECT a.name, SUM(d.amount) won, MAX(d.closed_at) last FROM accounts a
       JOIN deals d ON d.account_id = a.id JOIN stages s ON s.id = d.stage_id
      WHERE a.org_id = ? AND s.is_won = 1 ${scope.ownerId ? "AND d.owner_id = ?" : ""}
        AND NOT EXISTS (SELECT 1 FROM deals d2 JOIN stages s2 ON s2.id = d2.stage_id
                         WHERE d2.account_id = a.id AND s2.is_won = 0 AND s2.is_lost = 0)
      GROUP BY a.id ORDER BY won DESC`,
    scope.orgId, ...(scope.ownerId ? [scope.ownerId] : []),
  );
  if (expansion.length) {
    out.push({
      id: "expansion",
      severity: "opportunity",
      category: "Growth",
      title: `${expansion.length} paying customers have no open opportunity`,
      explanation: "Existing customers are typically the highest-converting source. These accounts have bought before but nobody is working a new deal with them.",
      evidence: expansion.slice(0, 4).map((e) => ({ label: e.name, value: `${inrCompact(e.won)} won · last ${e.last}` })),
      action: "Schedule account reviews with the top five and propose a relevant cross-sell (e.g. managed services after a migration).",
      link: "/accounts?filter=expansion",
    });
  }

  const order = { critical: 0, warning: 1, opportunity: 2, info: 3 };
  return out.sort((a, b) => order[a.severity] - order[b.severity]);
}

/** Deterministic plain-English briefing built from the insights. */
export function composeBriefing(insights: Insight[], name: string, periodLabel: string): string {
  const crit = insights.filter((i) => i.severity === "critical");
  const warn = insights.filter((i) => i.severity === "warning");
  const opp = insights.filter((i) => i.severity === "opportunity");
  const lines = [`Good day ${name.split(" ")[0]}. Here is where ${periodLabel} stands.`];
  if (crit.length) lines.push(`Needs attention now: ${crit.map((i) => i.title).join("; ")}.`);
  if (warn.length) lines.push(`Watch: ${warn.slice(0, 3).map((i) => i.title).join("; ")}.`);
  if (opp.length) lines.push(`Opportunity: ${opp.map((i) => i.title).join("; ")}.`);
  const first = crit[0] ?? warn[0] ?? opp[0];
  if (first) lines.push(`Suggested first move: ${first.action}`);
  return lines.join(" ");
}
